  `venue_location` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `venue_phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
