DROP TABLE IF EXISTS `offline_gateways`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `offline_gateways` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `language_id` int DEFAULT NULL,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `short_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `instructions` blob,
  `product_checkout_status` int NOT NULL DEFAULT '0',
  `serial_number` int NOT NULL DEFAULT '0',
  `is_receipt` tinyint NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `package_order_status` tinyint NOT NULL DEFAULT '0',
  `course_checkout_status` tinyint NOT NULL DEFAULT '1',
  `donation_checkout_status` tinyint NOT NULL DEFAULT '1' COMMENT '1 - active, 2 - deactive',
  `event_checkout_status` tinyint NOT NULL DEFAULT '1' COMMENT '1 - active, 0 - deactive',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

